sql_query:
SELECT "Year"
FROM clinical_trials
WHERE "Cancer type" = 'Non-Small Cell Lung' AND "Name of ICI" = 'Nivolumab' AND "Trial phase" = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Year" AS source_value FROM clinical_trials WHERE "Cancer type" = 'Non-Small Cell Lung' AND "Name of ICI" = 'Nivolumab' AND "Trial phase" = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_era_bucket(source_value) AS "era"
FROM base;
